result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/src/watch.js", "content": "import * as THREE from 'three';

const TAU = Math.PI * 2;

/**
 * Create a procedural 3D wristwatch.
 *
 * The returned THREE.Group contains:
 *  - a case built from a CylinderGeometry
 *  - a dial disc (flat cylinder) on top of the case
 *  - exactly 12 hour-tick meshes arranged around the dial
 *  - three articulated hand groups named "hourHand", "minuteHand" and
 *    "secondHand", each pivoted at the dial center (rotation about z).
 *
 * No renderer and no DOM are involved; the group is fully headless.
 */
export function createWatch() {
  const watch = new THREE.Group();
  watch.name = 'watch';

  // ---- Materials (shared, cheap MeshStandardMaterials) --------------------
  const caseMaterial = new THREE.MeshStandardMaterial({
    color: 0xb0b7c0,
    metalness: 0.9,
    roughness: 0.25,
  });
  const dialMaterial = new THREE.MeshStandardMaterial({
    color: 0x101418,
    metalness: 0.2,
    roughness: 0.7,
  });
  const tickMaterial = new THREE.MeshStandardMaterial({
    color: 0xf2f2f2,
    metalness: 0.1,
    roughness: 0.4,
  });

  // ---- Case ---------------------------------------------------------------
  // A cylinder standing on its axis (z), so the dial faces +z.
  const caseGeometry = new THREE.CylinderGeometry(1.15, 1.15, 0.35, 48);
  const caseMesh = new THREE.Mesh(caseGeometry, caseMaterial);
  caseMesh.name = 'case';
  caseMesh.rotation.x = Math.PI / 2; // orient cylinder axis along z
  caseMesh.position.z = -0.175; // top face flush with z = 0
  watch.add(caseMesh);

  // ---- Dial ---------------------------------------------------------------
  const dialGeometry = new THREE.CylinderGeometry(1.05, 1.05, 0.02, 48);
  const dial = new THREE.Mesh(dialGeometry, dialMaterial);
  dial.name = 'dial';
  dial.rotation.x = Math.PI / 2;
  dial.position.z = -0.01;
  watch.add(dial);

  // ---- Hour ticks (exactly 12) --------------------------------------------
  const tickGeometry = new THREE.BoxGeometry(0.04, 0.16, 0.01);
  const TICK_RADIUS = 0.92;
  for (let i = 0; i < 12; i++) {
    const angle = (i / 12) * TAU; // 12 o'clock at +y, clockwise numbering
    const tick = new THREE.Mesh(tickGeometry, tickMaterial);
    tick.name = `hourTick-${i}`;
    const x = -Math.sin(angle) * TICK_RADIUS;
    const y = Math.cos(angle) * TICK_RADIUS;
    tick.position.set(x, y, 0.005);
    tick.rotation.z = -angle; // keep each tick radially oriented
    watch.add(tick);
  }

  // ---- Hands ---------------------------------------------------------------
  // Each hand is a named group pivoted at the dial center (origin). Rotating
  // the group about z sweeps the hand around the dial; negative z rotation is
  // clockwise when viewed from +z.
  watch.add(
    createHand('secondHand', 0.95, 0.012, 0xd94f3d, 0.02),
    createHand('minuteHand', 0.78, 0.02, 0xf2f2f2, 0.03),
    createHand('hourHand', 0.5, 0.03, 0xf2f2f2, 0.04)
  );

  return watch;
}

/**
 * Build one articulated hand: a named pivot group containing an elongated box
 * whose geometry is offset so it extends along +y from the pivot.
 */
function createHand(name, length, width, color, zOffset) {
  const pivot = new THREE.Group();
  pivot.name = name;

  const material = new THREE.MeshStandardMaterial({
    color,
    metalness: 0.3,
    roughness: 0.35,
  });
  const geometry = new THREE.BoxGeometry(width, length, 0.015);
  geometry.translate(0, length / 2, 0); // pivot at the base of the hand

  const blade = new THREE.Mesh(geometry, material);
  blade.name = `${name}-blade`;
  blade.position.z = zOffset;
  pivot.add(blade);

  // Small counterweight behind the pivot for visual balance.
  const counterweightGeometry = new THREE.CircleGeometry(width * 1.6, 16);
  const counterweight = new THREE.Mesh(counterweightGeometry, material);
  counterweight.name = `${name}-counterweight`;
  counterweight.position.z = zOffset;
  pivot.add(counterweight);

  return pivot;
}

/**
 * Set the displayed time by rotating the hands about z.
 *
 * Clockwise motion equals negative rotation about +z. The hour hand accounts
 * for fractional minutes/hours (it moves continuously as minutes elapse).
 *
 * @param {THREE.Group} watch group returned by createWatch()
 * @param {number} h hours (0-23; wraps via modulo 12)
 * @param {number} m minutes (0-59, fractional allowed)
 * @param {number} s seconds (0-59, fractional allowed)
 */
export function setWatchTime(watch, h, m, s) {
  const hourHand = watch.getObjectByName('hourHand');
  const minuteHand = watch.getObjectByName('minuteHand');
  const secondHand = watch.getObjectByName('secondHand');

  if (!hourHand || !minuteHand || !secondHand) {
    throw new Error('setWatchTime requires a watch created by createWatch()');
  }

  const minuteFraction = (m % 60) / 60;
  const secondFraction = (s % 60) / 60;

  // Full turn every 12 hours, including fractional progress from minutes.
  hourHand.rotation.z = -TAU * (((h % 12) + minuteFraction) / 12);

  // Full turn per hour, including fractional progress from seconds.
  minuteHand.rotation.z = -TAU * ((m % 60) / 60);

  // Full turn per minute.
  secondHand.rotation.z = -TAU * secondFraction;
}
