result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/test/watch.test.js", "content": "import { describe, it, expect } from 'vitest';
import * as THREE from 'three';
import { createWatch, setWatchTime } from '../src/watch.js';

describe('createWatch()', () => {
  it('returns a THREE.Group', () => {
    const watch = createWatch();
    expect(watch).toBeInstanceOf(THREE.Group);
  });

  it('exposes the three hands by name, pivoted at the dial center', () => {
    const watch = createWatch();
    const hourHand = watch.getObjectByName('hourHand');
    const minuteHand = watch.getObjectByName('minuteHand');
    const secondHand = watch.getObjectByName('secondHand');

    expect(hourHand).toBeDefined();
    expect(minuteHand).toBeDefined();
    expect(secondHand).toBeDefined();

    for (const hand of [hourHand, minuteHand, secondHand]) {
      expect(hand).toBeInstanceOf(THREE.Group);
      // Pivot sits at the dial center (origin of the watch group).
      expect(hand.position.x).toBe(0);
      expect(hand.position.y).toBe(0);
    }
  });

  it('has exactly 12 hour-tick meshes', () => {
    const watch = createWatch();
    let tickCount = 0;
    watch.traverse((obj) => {
      if (obj.isMesh && obj.name.startsWith('hourTick')) tickCount++;
    });
    expect(tickCount).toBe(12);
  });

  it('contains a case and a dial mesh', () => {
    const watch = createWatch();
    const caseMesh = watch.getObjectByName('case');
    const dial = watch.getObjectByName('dial');
    expect(caseMesh).toBeDefined();
    expect(dial).toBeDefined();
    expect(caseMesh.geometry).toBeInstanceOf(THREE.CylinderGeometry);
  });
});

describe('setWatchTime()', () => {
  it('points minuteHand at 12 and hourHand at 3 for 3:00:00', () => {
    const watch = createWatch();
    setWatchTime(watch, 3, 0, 0);

    expect(watch.getObjectByName('hourHand').rotation.z).toBeCloseTo(
      -Math.PI / 2,
      6
    );
    expect(watch.getObjectByName('minuteHand').rotation.z).toBeCloseTo(0, 6);
  });

  it('sweeps minuteHand -PI and hourHand -PI/12 from 12:00 to 12:30', () => {
    const watch = createWatch();
    setWatchTime(watch, 12, 0, 0);

    const startMinute = watch.getObjectByName('minuteHand').rotation.z;
    const startHour = watch.getObjectByName('hourHand').rotation.z;

    setWatchTime(watch, 12, 30, 0);

    const deltaMinute =
      watch.getObjectByName('minuteHand').rotation.z - startMinute;
    const deltaHour = watch.getObjectByName('hourHand').rotation.z - startHour;

    expect(deltaMinute).toBeCloseTo(-Math.PI, 6);
    expect(deltaHour).toBeCloseTo(-Math.PI / 12, 6);
  });

  it('rotates the secondHand a full clockwise turn per minute at fixed h:m', () => {
    const watch = createWatch();
    setWatchTime(watch, 10, 15, 0);
    const start = watch.getObjectByName('secondHand').rotation.z;
    setWatchTime(watch, 10, 16, 0);
    const delta = watch.getObjectByName('secondHand').rotation.z - start;
    expect(delta).toBeCloseTo(-Math.PI * 2, 6);
  });
});
"})
